Object.assign(SNIP,{});PRESET_NOTES["l7"]={"Ví dụ: Chèn vào đầu bằng cách dịch": "Mảng dự trữ một ô trống ở cuối. Dời từ PHẢI sang TRÁI: a[4] = a[3], a[3] = a[2], … rồi mới đặt x vào a[0]. Dời từ trái sang sẽ ghi đè mất dữ liệu. n phần tử cần n lần dời: O(n).", "Ví dụ: Xóa phần tử bằng cách dịch": "Xóa a[1]: các phần tử phía sau dời sang trái một ô, từ trái sang phải. Ô cuối không còn dùng (n giảm 1).", "Ví dụ: insert và erase của vector": "Một dòng insert hay erase vẫn dời các ô phía sau, chỉ là thư viện làm thay bạn. Bộ đếm bước tính cả chi phí đó.", "Ví dụ: Đánh số từ 1": "Khai báo n + 1 ô, dùng a[1..n], a[0] bỏ trống. “Vị trí 2” trong đề chính là a[2] trong code, không phải trừ 1.", "Ví dụ: Nhiều bộ test": "Mỗi bộ test khai báo lại tong = 0 bên trong vòng lặp. Nếu để tong ở ngoài và quên đặt lại, bộ test sau sẽ cộng dồn kết quả của bộ trước."};EX_HINTS["l7"]=[["Phần tử thứ p (đếm từ 1) nằm ở chỉ số p − 1.", "Dời từ phải sang trái: for (i = n; i > p − 1; i--) a[i] = a[i − 1];", "Cũng có thể dùng a.insert(a.begin() + p − 1, x) với vector đúng n phần tử."], ["Giữ chỉ số k là số phần tử đã giữ lại. Gặp a[i] khác x thì chép xuống a[k] rồi tăng k.", "Bất biến: a[0..k-1] là các phần tử khác x trong a[0..i-1], đúng thứ tự.", "Mỗi phần tử được chép tối đa một lần: O(n). Gọi erase cho từng phần tử bằng x có thể tới O(n²)."], ["Giữ hai số lớn nhất m1 ≥ m2. Số mới lớn hơn m1 thì m1 cũ thành m2.", "Khởi tạo lại m1, m2 cho TỪNG bộ test (khai báo bên trong vòng lặp).", "Tổng có thể tới 2 · 10^9: dùng long long."]];
/* ===================== BÀI 7 · Mảng, vector và chỉ số ===================== */
/* Bài 7 · Mảng, vector và chỉ số
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR7=[{label:"Ví dụ: Chèn vào đầu bằng cách dịch",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {4, 7, 2, 5, 0};\n    int n = 4;\n    int x = 9;\n    for (int i = n; i > 0; i--) {\n        a[i] = a[i - 1];\n    }\n    a[0] = x;\n    n++;\n    for (int i = 0; i < n; i++) cout << a[i] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i"]}],predict:[{line:10,v:"i",q:"Ô nào sắp được ghi đè ở bước này? (bấm ô a[i])"}],py:{code:"a = [4, 7, 2, 5, 0]\nn = 4\nx = 9\nfor i in range(n, 0, -1):\n    a[i] = a[i - 1]\na[0] = x\nn += 1\nprint(*a[:n])",predict:[{line:5,v:"i",q:"Ô nào sắp được ghi đè ở bước này? (bấm ô a[i])"}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 4, 7, 2, 5, 0 };\n        int n = 4;\n        int x = 9;\n        for (int i = n; i > 0; i--)\n        {\n            a[i] = a[i - 1];\n        }\n        a[0] = x;\n        n++;\n        for (int i = 0; i < n; i++) Console.Write(a[i] + \" \");\n        Console.WriteLine();\n    }\n}",predict:[{line:12,v:"i",q:"Ô nào sắp được ghi đè ở bước này? (bấm ô a[i])"}]}},{label:"Ví dụ: Xóa phần tử bằng cách dịch",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {4, 7, 2, 5, 8};\n    int n = 5;\n    int p = 1;\n    for (int i = p; i < n - 1; i++) {\n        a[i] = a[i + 1];\n    }\n    n--;\n    for (int i = 0; i < n; i++) cout << a[i] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i","p"],range:["0","n-1"]}],py:{code:"a = [4, 7, 2, 5, 8]\nn = 5\np = 1\nfor i in range(p, n - 1):\n    a[i] = a[i + 1]\nn -= 1\nprint(*a[:n])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 4, 7, 2, 5, 8 };\n        int n = 5;\n        int p = 1;\n        for (int i = p; i < n - 1; i++)\n        {\n            a[i] = a[i + 1];\n        }\n        n--;\n        for (int i = 0; i < n; i++) Console.Write(a[i] + \" \");\n        Console.WriteLine();\n    }\n}"}},{label:"Ví dụ: insert và erase của vector",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {4, 7, 2, 5};\n    v.insert(v.begin() + 1, 9);\n    v.erase(v.begin());\n    v.push_back(6);\n    for (int x : v) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"v"}],py:{label:"Ví dụ: insert, pop và append của list",code:"v = [4, 7, 2, 5]\nv.insert(1, 9)\nv.pop(0)\nv.append(6)\nprint(*v)",viz:[{type:"cells",of:"v"}],note:"v.insert(1, 9) và v.pop(0) viết một dòng nhưng bên trong vẫn dời các phần tử phía sau: O(n). v.append(6) và v.pop() (bỏ phần tử cuối) mới là O(1)."},cs:{label:"Ví dụ: Insert và RemoveAt của List",code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        List<int> v = new List<int> { 4, 7, 2, 5 };\n        v.Insert(1, 9);\n        v.RemoveAt(0);\n        v.Add(6);\n        foreach (int x in v) Console.Write(x + \" \");\n        Console.WriteLine();\n    }\n}",note:"List<int> là mảng tự dãn của C#. Insert(i, x) và RemoveAt(i) dời các phần tử phía sau, nên tốn O(n); Add(x) thêm vào cuối, trung bình O(1)."}},{label:"Ví dụ: Đánh số từ 1",input:"5\n10 20 30 40 50\n2 5",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> a(n + 1);\n    for (int i = 1; i <= n; i++) cin >> a[i];\n    int p, q;\n    cin >> p >> q;\n    cout << \"a[\" << p << \"] + a[\" << q << \"] = \" << a[p] + a[q] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a"}],py:{code:"n = int(input())\na = [0] + list(map(int, input().split()))\np, q = map(int, input().split())\nprint(f\"a[{p}] + a[{q}] = {a[p] + a[q]}\")",note:"Thêm một phần tử 0 vào đầu list ([0] + …) để a[1] là số đầu tiên của đề: code giống hệt công thức trong đề."},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        string[] s = Console.ReadLine().Split();\n        int[] a = new int[n + 1];\n        for (int i = 1; i <= n; i++) a[i] = int.Parse(s[i - 1]);\n        string[] t = Console.ReadLine().Split();\n        int p = int.Parse(t[0]), q = int.Parse(t[1]);\n        Console.WriteLine($\"a[{p}] + a[{q}] = {a[p] + a[q]}\");\n    }\n}",note:"Mảng n + 1 phần tử, bỏ trống a[0]: phần tử thứ i của đề nằm đúng ở a[i]. Chuỗi $\"…{biểu thức}…\" chèn giá trị của biểu thức vào chuỗi."}},{label:"Ví dụ: Nhiều bộ test",input:"3\n2\n1 2\n3\n5 5 5\n1\n-7",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int t;\n    cin >> t;\n    for (int tc = 1; tc <= t; tc++) {\n        int n;\n        cin >> n;\n        long long tong = 0;\n        for (int i = 0; i < n; i++) {\n            int x;\n            cin >> x;\n            tong += x;\n        }\n        cout << \"Test \" << tc << \": \" << tong << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"vars",names:["tc","n","tong"]}],py:{code:"t = int(input())\nfor tc in range(1, t + 1):\n    n = int(input())\n    a = list(map(int, input().split()))\n    tong = 0\n    for x in a:\n        tong += x\n    print(f\"Test {tc}: {tong}\")"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int t = int.Parse(Console.ReadLine());\n        for (int tc = 1; tc <= t; tc++)\n        {\n            int n = int.Parse(Console.ReadLine());\n            int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            long tong = 0;\n            for (int i = 0; i < n; i++)\n            {\n                tong += a[i];\n            }\n            Console.WriteLine(\"Test \" + tc + \": \" + tong);\n        }\n    }\n}"}}];
const sim7=makeSim2(document.getElementById("sim-l7"),{id:"s7",presets:PR7});
makeEx2(document.getElementById("ex-l7"),sim7,[{t:"Chèn vào vị trí p",d:"Đầu vào: n (1 ≤ n ≤ 1000), dãy a₁ … aₙ, rồi hai số p và x (1 ≤ p ≤ n + 1). Chèn x vào để x trở thành phần tử thứ p của dãy. Đầu ra: dãy mới (n + 1 số).",tests:[{in:"4\n4 7 2 5\n2 9",out:"4 9 7 2 5"},{in:"3\n1 2 3\n1 0",out:"0 1 2 3"},{in:"3\n1 2 3\n4 9",out:"1 2 3 9"},{in:"1\n5\n1 -1",out:"-1 5"}],start:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> a(n + 1);\n    for (int i = 0; i < n; i++) cin >> a[i];\n    int p, x;\n    cin >> p >> x;\n    // dời các phần tử từ vị trí p - 1 sang phải một ô (từ cuối về)\n    return 0;\n}",py:{start:"n = int(input())\na = list(map(int, input().split()))\np, x = map(int, input().split())\na.append(0)   # thêm một ô ở cuối để có chỗ dời\n# dời các phần tử từ vị trí p - 1 sang phải một ô (từ cuối về)",hints:["Phần tử thứ p (đếm từ 1) nằm ở chỉ số p − 1.","Dời từ phải sang trái: for i in range(n, p - 1, -1): a[i] = a[i - 1].","Cách ngắn: a.insert(p - 1, x) (sau khi bỏ dòng append) cũng là O(n) bên trong."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        string[] t = Console.ReadLine().Split();\n        int p = int.Parse(t[0]), x = int.Parse(t[1]);\n        int[] b = new int[n + 1];\n        // chép a sang b, rồi dời các phần tử từ vị trí p - 1 sang phải một ô (từ cuối về)\n    }\n}",hints:["Mảng C# có kích thước cố định: tạo mảng b dài n + 1 rồi chép a sang. Phần tử thứ p (đếm từ 1) nằm ở chỉ số p − 1.","Dời từ phải sang trái: for (int i = n; i > p − 1; i--) b[i] = b[i − 1];","Cũng có thể dùng List<int> và gọi Insert(p − 1, x). In cả mảng: string.Join(\" \", b)."]}},{t:"Xóa các phần tử bằng x",d:"Đầu vào: n (1 ≤ n ≤ 10^5), dãy n số, rồi số x. Xóa mọi phần tử bằng x, giữ nguyên thứ tự các phần tử còn lại. Đầu ra: số phần tử còn lại, rồi dòng các phần tử đó. Mỗi lần xóa mà dời cả mảng thì quá chậm: hãy làm trong một lần duyệt.",tests:[{in:"6\n1 3 2 3 3 4\n3",out:"3\n1 2 4"},{in:"3\n5 5 5\n5",out:"0\n"},{in:"4\n1 2 3 4\n9",out:"4\n1 2 3 4"},{in:"1\n7\n7",out:"0\n"}],start:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> a(n);\n    for (int& v : a) cin >> v;\n    int x;\n    cin >> x;\n    // k = số phần tử đã giữ lại; phần tử khác x được chép xuống a[k]\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>i%2).join(" ")+"\n0",ns:[1000,4000,16000],need:"n",limit:n=>16*n+200,why:"Mỗi lần xóa rồi dời cả phần còn lại là O(n), nhiều lần xóa thành O(n²). Hãy chép các phần tử giữ lại xuống đầu mảng trong một lần duyệt."},py:{start:"n = int(input())\na = list(map(int, input().split()))\nx = int(input())\n# k = số phần tử đã giữ lại; phần tử khác x được chép xuống a[k]",hints:["Giữ chỉ số k là số phần tử đã giữ lại. Gặp a[i] khác x thì chép xuống a[k] rồi tăng k.","Bất biến: a[0..k-1] là các phần tử khác x trong a[0..i-1], đúng thứ tự.","Gọi a.remove(x) nhiều lần có thể tới O(n²). Cách Python gọn: [v for v in a if v != x], cũng O(n)."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int x = int.Parse(Console.ReadLine());\n        // k = số phần tử đã giữ lại; phần tử khác x được chép xuống a[k]\n    }\n}",hints:["Giữ chỉ số k là số phần tử đã giữ lại. Gặp a[i] khác x thì chép xuống a[k] rồi tăng k.","Bất biến: a[0..k-1] là các phần tử khác x trong a[0..i-1], đúng thứ tự.","Mỗi phần tử được chép tối đa một lần: O(n). Gọi RemoveAt của List cho từng phần tử bằng x có thể tới O(n²)."]}},{t:"Tổng nhiều bộ test",d:"Đầu vào: t (1 ≤ t ≤ 100) bộ test; mỗi bộ gồm n (1 ≤ n ≤ 1000) và n số nguyên (|aᵢ| ≤ 10^9). Đầu ra: với mỗi bộ test, in tổng lớn nhất của hai phần tử ở hai vị trí khác nhau (nếu n = 1 thì in chính phần tử đó).",tests:[{in:"2\n3\n1 5 3\n4\n-1 -2 -3 -4",out:"8\n-3"},{in:"1\n1\n42",out:"42"},{in:"1\n2\n1000000000 1000000000",out:"2000000000"},{in:"3\n2\n0 0\n3\n7 7 1\n1\n-5",out:"0\n14\n-5"}],start:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int t;\n    cin >> t;\n    for (int tc = 0; tc < t; tc++) {\n        // đọc n, dãy; tìm hai số lớn nhất\n    }\n    return 0;\n}",py:{start:"t = int(input())\nfor tc in range(t):\n    # đọc n, dãy; tìm hai số lớn nhất\n    pass",hints:["Giữ hai số lớn nhất m1 ≥ m2. Số mới lớn hơn m1 thì m1 cũ thành m2.","Khởi tạo lại m1, m2 cho TỪNG bộ test (gán bên trong vòng lặp)."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int t = int.Parse(Console.ReadLine());\n        for (int tc = 0; tc < t; tc++)\n        {\n            // đọc n, dãy; tìm hai số lớn nhất\n        }\n    }\n}",hints:["Giữ hai số lớn nhất m1 ≥ m2. Số mới lớn hơn m1 thì m1 cũ thành m2.","Khởi tạo lại m1, m2 cho TỪNG bộ test (khai báo bên trong vòng lặp).","Tổng có thể tới 2 · 10^9: dùng long (đọc dãy bằng long.Parse)."]}}]);

